import { __ } from '@wordpress/i18n';
import { useState, useEffect, useRef } from '@wordpress/element';
import {
	insert,
	insertObject,
	slice,
	getTextContent,
	useAnchor,
} from '@wordpress/rich-text';
import type { RichTextValue } from '@wordpress/rich-text';
// @ts-expect-error Block Editor not fully typed yet.
import { RichTextToolbarButton } from '@wordpress/block-editor';
import { Popover } from '@wordpress/components';
import { ValidatedInputControl, Link } from '@wordpress/ui';
import { math as icon } from '@wordpress/icons';
import type { FormatEditProps } from '../types';

interface InlineMathUIProps {
	value: RichTextValue;
	onChange: ( value: RichTextValue ) => void;
	activeObjectAttributes: Record< string, string >;
	contentRef: React.RefObject< HTMLElement >;
	/**
	 * Resolves once `@wordpress/latex-to-mathml` has loaded; undefined until then.
	 */
	latexToMathML?: (
		latex: string,
		options?: { displayMode?: boolean }
	) => string;
}

const name = 'core/math';
const title = __( 'Math' );

function InlineUI( {
	value,
	onChange,
	activeObjectAttributes,
	contentRef,
	latexToMathML,
}: InlineMathUIProps ) {
	const [ latex, setLatex ] = useState(
		activeObjectAttributes[ 'data-latex' ] || ''
	);
	const [ error, setError ] = useState< string | null >( null );
	const formRef = useRef< HTMLFormElement >( null );

	const popoverAnchor = useAnchor( {
		// eslint-disable-next-line react-hooks/refs
		editableContentElement: contentRef.current,
		settings: math,
	} );

	// Update the math object in real-time as the user types
	const handleLatexChange = ( newLatex: string ) => {
		setLatex( newLatex );

		let mathML = '';
		if ( newLatex && latexToMathML ) {
			try {
				mathML = latexToMathML( newLatex, { displayMode: false } );
				setError( null );
			} catch ( err ) {
				setError(
					err instanceof Error
						? err.message
						: __( 'Could not parse the LaTeX math syntax.' )
				);
			}
		} else {
			setError( null );
		}

		const newReplacements = value.replacements.slice();
		newReplacements[ value.start ] = {
			type: name,
			attributes: {
				'data-latex': newLatex,
			},
			innerHTML: mathML,
		};

		onChange( {
			...value,
			replacements: newReplacements,
		} );
	};

	return (
		<Popover
			placement="bottom-start"
			offset={ 8 }
			focusOnMount={ false }
			anchor={ popoverAnchor }
			// Surface any parsing error before focus leaves the popover.
			// An invalid field is refocused, keeping the popover open.
			onFocusOutside={ () => formRef.current?.reportValidity() }
			className="block-editor-format-toolbar__math-popover"
		>
			<form
				ref={ formRef }
				style={ { minWidth: '300px', padding: '16px' } }
				onSubmit={ ( event ) => event.preventDefault() }
			>
				<ValidatedInputControl
					label={ __( 'LaTeX math syntax' ) }
					value={ latex }
					customValidity={
						error ? { type: 'invalid', message: error } : undefined
					}
					onValueChange={ handleLatexChange }
					placeholder={ __( 'e.g., x^2, \\frac{a}{b}, \\sqrt{x}' ) }
					autoComplete="off"
					className="block-editor-format-toolbar__math-input"
				/>
				<Link
					openInNewTab
					className="block-editor-format-toolbar__math-learn-more"
					href={ __(
						'https://wordpress.org/documentation/article/math-block/'
					) }
				>
					{ __( 'Learn more about LaTeX syntax' ) }
				</Link>
			</form>
		</Popover>
	);
}

function Edit( {
	value,
	onChange,
	onFocus,
	isObjectActive,
	activeObjectAttributes,
	contentRef,
}: FormatEditProps ) {
	const [ latexToMathML, setLatexToMathML ] =
		useState<
			( latex: string, options?: { displayMode?: boolean } ) => string
		>();

	useEffect( () => {
		import( '@wordpress/latex-to-mathml' ).then( ( module ) => {
			setLatexToMathML( () => module.default );
		} );
	}, [] );

	function onClick() {
		let newValue;

		if ( isObjectActive ) {
			// Revert the active math object to its LaTeX source so clicking
			// the button toggles back to the exact text it was created from.
			// Keep the restored text selected so it can be edited or
			// re-marked right away.
			const latex = activeObjectAttributes[ 'data-latex' ] || '';
			newValue = insert( value, latex );
			newValue.start = newValue.end - latex.length;
		} else {
			// If there's a selection, seed the format with it so you can type
			// LaTeX inline and then mark it as math.
			const selectedText = getTextContent( slice( value ) );
			let innerHTML = '';
			if ( selectedText && latexToMathML ) {
				try {
					innerHTML = latexToMathML( selectedText, {
						displayMode: false,
					} );
				} catch {
					// Leave unrendered; the popover opens with the text
					// prefilled so the expression can be corrected.
				}
			}
			newValue = insertObject( value, {
				type: name,
				attributes: { 'data-latex': selectedText },
				innerHTML,
			} );
			newValue.start = newValue.end - 1;
		}

		onChange( newValue );
		onFocus();
	}

	return (
		<>
			<RichTextToolbarButton
				icon={ icon }
				title={ title }
				onClick={ onClick }
				isActive={ isObjectActive }
			/>
			{ isObjectActive && (
				<InlineUI
					value={ value }
					onChange={ onChange }
					activeObjectAttributes={ activeObjectAttributes }
					contentRef={ contentRef }
					latexToMathML={ latexToMathML }
				/>
			) }
		</>
	);
}

export const math = {
	name,
	title,
	tagName: 'math',
	className: null,
	attributes: {
		'data-latex': 'data-latex',
	},
	contentEditable: false,
	edit: Edit,
};
